/* Callout properties - applied after others */
body .callout[data-callout*="text_glow"] {
    text-shadow: 0 0 9px var(--glow-color1);
}
body .callout[data-callout*="text_light_glow"] {
    text-shadow: 0 0 4px var(--glow-color2);
}
body .callout[data-callout*="callout_glow"]  {
    box-shadow: inset 0 0 15px color-mix(in srgb, var(--glow-color2), transparent 20%);
    text-shadow: 0 0 3px var(--glow-color2);
}
body .callout[data-callout*="cutout"] {
    box-shadow: inset 5px 5px 15px color-mix(in srgb, var(--shadow-color), transparent 50%);
	border: none;
}
body .callout[data-callout*="no_icon"]  {
    --callout-icon: none;
}
body .callout[data-callout*="no_title"] {
	--callout-title-size: 0px;
	padding-top: 2px;
}
body .callout[data-callout*="no_title"] .callout-title {
	visibility: hidden;
}
body .callout[data-callout*="no_border"] {
	border: none;
}
body .callout[data-callout*="solid_border"] {
	border-style: solid;
}
body .callout[data-callout*="no_bg"] {
	background: none;
}
body .callout[data-callout*="no_stamp"] {
	background-image: none;
}
body .callout[data-callout*="no_glow"] {
	box-shadow: none;
}
body .callout[data-callout*="white_text"] {
	color: white;
}
body .callout[data-callout*="nothing"] {
    --callout-icon: none;
	--callout-title-size: 0px;
	padding-top: 2px;
	box-shadow: none;
	background: none;
	border: none;
}
body .callout[data-callout*="nothing"] .callout-title {
	visibility: hidden;
}
body .callout[data-callout*="fixed_bg"] {
	background-attachment: fixed;
	background-size: 100% auto;
	background-repeat: no-repeat;
	background-position-x: 0px;
	background-position-y: 10%;
}
body .callout[data-callout*="bg_lines"] {
	background-image: var(--nbg-whim-lines);
	background-size: auto;
	background-position: initial;
	background-repeat: unset;
}
body .callout[data-callout*="bg_net"] {
	--nett: 75%;
	--netsize: 120px;
	--netsizewidth: 122px;
	--callout-net-color: color-mix(in srgb, var(--callout-color), transparent 80%);
	background: 
		repeating-linear-gradient(45deg, var(--callout-net-color), var(--callout-net-color) var(--netsize), color-mix(in srgb, var(--nbg-draw-color), transparent var(--nett)) var(--netsize), color-mix(in srgb, var(--nbg-draw-color), transparent var(--nett)) var(--netsizewidth)),
		repeating-linear-gradient(135deg, var(--callout-net-color), var(--callout-net-color) var(--netsize), color-mix(in srgb, var(--nbg-draw-color), transparent var(--nett)) var(--netsize), color-mix(in srgb, var(--nbg-draw-color), transparent var(--nett)) var(--netsizewidth))
		;
	background-position: 50% 50%;
    background-attachment: fixed;
}
body .callout[data-callout*="callout_red"] {
	--callout-color: var(--color-red);
}
body .callout[data-callout*="callout_orange"] {
	--callout-color: var(--color-orange);
}
body .callout[data-callout*="callout_yellow"] {
	--callout-color: var(--color-yellow);
}
body .callout[data-callout*="callout_green"] {
	--callout-color: var(--color-green);
}
body .callout[data-callout*="callout_cyan"] {
	--callout-color: var(--color-cyan);
}
body .callout[data-callout*="callout_blue"] {
	--callout-color: var(--color-blue);
}
body .callout[data-callout*="callout_purple"] {
	--callout-color: var(--color-purple);
}
body .callout[data-callout*="callout_pink"] {
	--callout-color: var(--color-pink);
}
body .callout[data-callout*="callout_whim"] {
	--callout-color: var(--whim-color);
}
body .callout[data-callout*="callout_light"] {
	--callout-color: var(--lw);
}
body .callout[data-callout*="callout_bright"] {
	--callout-color: var(--bcon);
}
body .callout[data-callout*="callout_dark"] {
	--callout-color: var(--dw);
}
body .callout[data-callout*="callout_black"] {
	--callout-color: black;
}
body .callout[data-callout*="callout_contrast"] {
	--callout-color: var(--dcon);
}
body .callout[data-callout*="popout"]:hover {
	transform: scale(1.05);
}
body .callout[data-callout*="border_strong"] {
	border-color: var(--dark-whim);
	border-width: 3px;
}
body .callout[data-callout*="big_text"] {
	font-size: 1.75em;
}
body .callout[data-callout*="gigantext"] {
	font-size: 4em;
	font-weight: 800;
}
body .callout[data-callout*="text_cut"] {
	color: transparent;
  	background-clip: text;
    --callout-icon: none;
	--callout-title-size: 0px;
	padding-top: 2px;
	background-color: var(--callout-color);

}
body .callout[data-callout*="text_cut"] .callout-title {
	visibility: hidden;
}
body .callout[data-callout*="text_cut"]:hover {
	border: none;
}
body .callout[data-callout*="header_font"] {
	font-family: var(--hfont);
}

/* Final callout styling */
.callout {
	background-color: color-mix(in srgb, var(--callout-color), transparent 60%);
	--icon-size: var(--callout-icon-size);
	color: color-mix(in srgb, var(--callout-color), var(--callout-lum) 60%);
}
.callout-title-inner {
	font-family: var(--hfont);
	font-weight: 200;
	font-size: var(--callout-title-size);
	color: color-mix(in srgb,var(--callout-color), var(--callout-lum) 30%);
}


